function catalogUniqueSlug(PDO $pdo,string $table,string $slug,int $exclude=0): string { $slug=cmsSlug($slug)?:'item';$base=$slug;$n=2;while(true){$sql='SELECT id FROM `'.$table.'` WHERE slug=:s'.($exclude?' AND id<>:id':'').' LIMIT 1';$st=$pdo->prepare($sql);$p=[':s'=>$slug];if($exclude)$p[':id']=$exclude;$st->execute($p);if(!$st->fetchColumn())return $slug;$slug=$base.'-'.$n++;}}
function catalogImageShared(PDO $pdo,string $path,int $exclude): bool {$s=$pdo->prepare('SELECT COUNT(*) FROM catalog_products WHERE image_path=:p AND id<>:id');$s->execute([':p'=>$path,':id'=>$exclude]);return (int)$s->fetchColumn()>0;}
