'description_en')?:null,':img'=>$val('image_path')?:null,':sku'=>$val('sku')?:null,':pr'=>$price!==''?(float)$price:null,':cur'=>$val('currency')?:null,':av'=>$availability,':f'=>cmsBool($val('is_featured')),':n'=>cmsBool($val('is_new')),':so'=>cmsInt($val('sort_order')),':ia'=>cmsBool($val('is_active'))]);$count++;}$pdo->commit();fclose($fh);cmsAudit('catalog.csv.import','catalog_products',(string)$count);cmsAdminRedirect($base.'?tab=import','تم استيراد/تحديث '.$count.' منتج.');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();fclose($fh);throw $e;}
